import jadx.api.*;import java.io.*;import java.nio.file.*;public class DecompileSelected{public static void main(String[]a)throws Exception{var cfg=new JadxArgs();cfg.setInputFile(new File(a[0]));cfg.setThreadsCount(2);cfg.setSkipResources(true);try(var d=new JadxDecompiler(cfg)){d.load();for(int i=2;i<a.length;i++){String name=a[i];var c=d.getClasses().stream().filter(x->x.getFullName().equals(name)).findFirst().orElseThrow();Files.writeString(Path.of(a[1],name+".java"),c.getCode());System.out.println(name);}}}}
